def read(ref):
 p=Path(ref['file']);assert p.stat().st_size<16*1024*1024
 raw=p.read_bytes();assert hashlib.sha256(raw).hexdigest()==ref['sha256'];return json.loads(raw)
prior={'file':'logs/review/diag_shared709763709766_claims_0600_01/snapshot.json','sha256':'c93d219d512a059bffbafc2b5883c6598604109e396af9a6bc36243552d92f54'}
