   raw=p.read_bytes();data=json.loads(raw);pr.update(reference=archive(raw,evidence,parent+'_result.json'),meta={k:data.get('_meta',{}).get(k) for k in ('start','end','exit_code')},metrics={k:data.get('metrics',{}).get(k) for k in ('status','error','errors','cleanup_errors','scene_runs','stages')})
  parents.append(pr)
  for assignment in unit['identity']['assignments']:
   scene=assignment['scene'];child=parent+'_c6_'+scene.lower();row={'name':child,'scene':scene,'job_id':owner['job_id'],'claim_reference':original['claim_reference'],'source_reported_counts':None,'independent_acceptance':None}
   log=ROOT/'logs/runs'/(child+'.log');row['log_exists']=log.is_file()
   if log.is_file():
    with log.open('rb') as f:head=f.read(4096).decode(errors='replace')
    row['original_log_header']=head.splitlines()[:5]
   p=ROOT/'results'/(child+'.json');row['result_exists']=p.is_file()
   if p.is_file():
    raw=p.read_bytes();data=json.loads(raw);m=data.get('metrics',{});row.update(source_reference=archive(raw,evidence,child+'_result.json'),meta={k:data.get('_meta',{}).get(k) for k in ('start','end','exit_code')},original_metrics={k:m.get(k) for k in ('status','error','errors','attempts','passed_by_class','black_frame_detected','cleanup_errors','scene_excluded')})
   journal=ROOT/'data/world_pairs/v2'/(child+'_attempts.jsonl');row['journal_exists']=journal.is_file()
   if journal.is_file():
    raw,extent=read_prefix(journal);row['journal_extent']=extent;row['journal_snapshot']=archive(raw,evidence,child+'_attempts.jsonl');row['source_reported_counts']=observed_counts(raw,scene)
   rows.append(row)
record={'observed_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'prior_claim_snapshot':prior,'parents':parents,'scenes':rows,'scope':'Only original archived complete journal prefixes and original metadata; live producer-reported candidates are not independent acceptance. Missing/unsealed sources remain unknown.'}
p=out/'snapshot.json'
with p.open('x') as f:json.dump(record,f,sort_keys=True,indent=2)
brief={'report':{'file':str(p.relative_to(ROOT)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()},'observed_at_utc':record['observed_at_utc'],'parents':parents,'scenes':[{k:r[k] for k in ('name','scene','job_id','result_exists','log_exists','journal_exists','source_reported_counts','original_metrics','meta','journal_extent') if k in r} for r in rows]}
print('G01_PROGRESS_SNAPSHOT: '+json.dumps(brief,sort_keys=True),flush=True);signal.alarm(0)

